// Pass artwork, base64. Apple silently rejects a .pkpass missing icon.png.
//
// The card matches the invite page dark band, so the logo is the cream
// wordmark with the red "mix", MIX & GREET baked in as line two because
// Wallet draws logoText to the RIGHT of the logo with no way to place it below.
//
// background.png is the invite poster overlay WITHOUT the photograph: ramp,
// 45rpm rings and disc, arcs, grain, vignette, then knocked back hard. Wallet
// blurs it and prints the fields over the top, so it has to read as depth
// rather than as a picture. There is no thumbnail: the card carries no
// special-guest photo, only their names.
export const PASS_IMAGES: Record<string, string> = {
  "background.png": "",
  "background@2x.png": "",
  "background@3x.png": "",
  "icon.png": "",
  "icon@2x.png": "",
  "icon@3x.png": "",
  "logo.png": "",
  "logo@2x.png": "",
  "logo@3x.png": ""
};
